const {spawn} = require('node:child_process');
const fs = require('node:fs');
const assert = require('node:assert/strict');
const chrome = spawn('/root/.cache/ms-playwright/chromium-1140/chrome-linux/chrome', ['--headless','--no-sandbox','--disable-dev-shm-usage','--disable-crashpad-for-testing','--disable-breakpad','--remote-debugging-pipe','--user-data-dir=/tmp/sam-priya-rsvp-review-pipe'], {stdio:['ignore','ignore','pipe','pipe','pipe']});
let next = 0, buffer = '', session;
const pending = new Map();
chrome.stderr.on('data', ()=>{});
chrome.stdio[4].on('data', data => {
  buffer += data;
  let end;
  while ((end = buffer.indexOf('\\0')) >= 0) {
    const raw = buffer.slice(0,end); buffer = buffer.slice(end+1);
    if ("'!raw) continue;
    const message = JSON.parse(raw);
    if (pending.has(message.id)) { const {resolve,reject} = pending.get(message.id); pending.delete(message.id); message.error ? reject(message.error) : resolve(message.result); }
  }
});
function cdp(method, params = {}, withSession = true) {
