 assert.equal(await evaluate('document.getElementById(\"confirmation\").hidden'),false);
 assert.equal(await evaluate('JSON.parse(localStorage.getItem(\"sam-priya-wedding-rsvp-2027\")).guests'),2);
 await evaluate('document.getElementById(\"edit-response\").click(); document.querySelector(\"[name=attendance][value=no]\").click()');
 assert.equal(await evaluate('document.getElementById(\"attending-fields\").hidden'),true);
 await evaluate('document.querySelector(\"[type=submit]\").click()');
 assert.equal(await evaluate('JSON.parse(localStorage.getItem(\"sam-priya-wedding-rsvp-2027\")).guests'),0);
 await evaluate('location.reload()');
 await new Promise(resolve=>setTimeout(resolve,400));
 assert.equal(await evaluate('document.getElementById(\"confirmation\").hidden'),false);
 await evaluate('document.getElementById(\"edit-response\").click(); document.querySelector(\"[name=attendance][value=yes]\").click(); document.getElementById(\"guest-count\").value=\"0\"; document.querySelector(\"[type=submit]\").click()');
 assert.equal(await evaluate('document.getElementById(\"count-error\").hidden'),false);
 await evaluate('document.getElementById(\"guest-count\").value=\"1\"; Storage.prototype.setItem = function(){throw new Error(\"blocked\")}; document.querySelector(\"[type=submit]\").click()');
 assert.equal(await evaluate('document.getElementById(\"save-error\").hidden'),false);
 console.log('PASS: empty-form validation, attendance, stepper, save, edit, decline, persistence, invalid count, blocked storage.');
 await cdp('Browser.close',{},false);
 clearTimeout(timeout);
})().catch(error=>{console.error(error);clearTimeout(timeout);chrome.kill();process.exitCode=1});
