from html.parser import HTMLParser
from pathlib import Path
import subprocess
class Check(HTMLParser):
    def __init__(self):
        super().__init__(); self.ids=set(); self.labels=[]; self.refs=[]; self.script=False; self.js=[]
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        if 'id' in a:
            assert a['id'] not in self.ids, 'duplicate id: '+a['id']
            self.ids.add(a['id'])
        if tag=='label' and 'for' in a: self.labels.append(a['for'])
        for attr in ('aria-describedby','aria-labelledby'):
            self.refs.extend(a.get(attr,'').split())
        if tag=='script': self.script=True
    def handle_endtag(self, tag):
        if tag=='script': self.script=False
    def handle_data(self, data):
        if self.script: self.js.append(data)
p=Check(); p.feed(Path('index.html').read_text())
assert set(p.labels+p.refs) <= p.ids, 'unresolved label or ARIA reference'
assert {'guest-name','guest-count','dietary','rsvp-form','confirmation'} <= p.ids
subprocess.run(['node','--check','-'],input=''.join(p.js),text=True,check=True)
print('PASS: HTML identifiers, field labels, ARIA references, required fields, and JavaScript syntax.')
